#include <WiFi.h>

#define WIFI_SSID "my-network"
#define WIFI_PASS "my-passphrase"

void connectWifi() {
  WiFi.begin(WIFI_SSID, WIFI_PASS);
  while (WiFi.status() != WL_CONNECTED) {
    delay(500);
  }
}
